schemas.schema-01-systematic.prisma:
/// Channel entity - Implements the channels management requirement, supporting the definition and configuration of sales/distribution channels (e.g., main website, partner sites, mobile app) within the systematic backbone. Channels represent different distribution fronts for the platform, allowing appropriate products and content to be mapped or scoped. Strict 3NF compliance is maintained by decoupling the channel entity from other business entities. Channels may be referenced externally by related domain tables (such as products, channel assignments).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each channel by universally unique identifier according to best practice.
  id String @id @db.Uuid

  /// Channel code: unique short identifier (e.g., 'WEB', 'MOBILE'). Used for programmatic lookups and internal configuration, atomic value. Unique across all channels.
  code String

  /// Human-readable channel name for UIs and management. Fully normalized, used in admin/service configurations.
  name String

  /// If true, channel is active; otherwise, channel is disabled for routing/service. Atomic flag, fully normalized. Used for toggling channel availability without deletion.
  enabled Boolean

  /// Row creation timestamp for audit trail and compliance, required for record keeping. 3NF: atomic.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp for audit/change tracking. Atomic, not pre-calculated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  aimall_backend_sections aimall_backend_sections[]
  aimall_backend_configurations aimall_backend_configurations[]
  aimall_backend_channel_assignments aimall_backend_channel_assignments[]

  @@unique([code])
  @@index([enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Section entity - Implements the requirement for UI/display content organization within channels. Sections are subdivisions (e.g., homepage banners, featured blocks) and strictly normalized. Channel_id is FK to channels, code is unique within channel. Soft deletion uses deleted_at. Used as a referencing entity for content/product/offer assignment modules in other domains. No denormalized data, all fields atomic. 3NF compliant.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each section in the system.
  id String @id @db.Uuid

  /// Belonged channel's {@link aimall_backend_channels.id}. Links section to a specific channel. This ensures clear channel/section-scoping. Non-nullable for data integrity.
  channel_id String @db.Uuid

  /// Section code, unique within channel, e.g., 'BANNER', 'DEALS'. Atomic value; fully 3NF; no repetition.
  code String

  /// Section display name: human readable, for admin/UI. Atomic data, normalized.
  name String

  /// Numeric order for display, atomic field, 3NF. Used for admin/UI ordering and rendering control.
  display_order Int @db.Integer

  /// If true, section is active/visible; admin toggle/control for soft suppressing/activating sections. 3NF, atomic field.
  enabled Boolean

  /// Creation timestamp for audit/logical tracing, no denormalization.
  created_at DateTime @db.Timestamptz

  /// Last change timestamp for auditing. No pre-calculation, atomic field. 3NF.
  updated_at DateTime @db.Timestamptz

  /// Logical deletion field: soft delete with timestamp, null if alive. Used for logical retention and audit. Nullable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_aimall_backend_sections_channel_id aimall_backend_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  aimall_backend_configurations aimall_backend_configurations[]

  @@unique([channel_id, code])
  @@index([enabled])
  @@index([channel_id, display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System Configuration entity - Implements requirement for global, channel, or section-scoped setting storage. Each configuration represents a setting (key/value) optionally scoped to channel or section. Used for feature toggles, platform-wide or channel-specific behaviors. Fully 3NF: no duplicated/denormalized/calculated fields, all settings atomic and change-tracked. Key+channel_id+section_id combination is unique to avoid overlap. All relationships are optional (global = both null).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique record id. Each config is a standalone setting.
  id String @id @db.Uuid

  /// Optional foreign key to {@link aimall_backend_channels.id}. Null = global config; for channel-level settings. Ensures normalized design. Soft constraint; referenced channel must exist if used.
  channel_id String? @db.Uuid

  /// Optional FK to {@link aimall_backend_sections.id}. Null = applies at global or channel settings; non-null = conf applies to given section. Retains 3NF, atomic references.
  section_id String? @db.Uuid

  /// Configuration key for setting, e.g., 'site_maintenance'. Atomic string key, unique per channel+section. No denormalization, single data point.
  key String

  /// Setting value in string form, to allow flexible data types (bool/int/JSON all as strings). Pure field, 3NF, atomic.
  value String

  /// Optional text explaining the configuration for admins, nullable. Used for documentation and operational clarity. No constraint; normalized; not required.
  description String?

  /// Row created time for compliance/auditability. Not null; not derived.
  created_at DateTime @db.Timestamptz

  /// Last change timestamp. 3NF: atomic field, not precomputed or denormalized.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_aimall_backend_configurations_channel_id aimall_backend_channels? @relation(fields: [channel_id], references: [id], onDelete: Cascade)
  fk_aimall_backend_configurations_section_id aimall_backend_sections? @relation(fields: [section_id], references: [id], onDelete: Cascade)

  @@unique([key, channel_id, section_id])
  @@index([channel_id])
  @@index([section_id])
  @@index([key(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-actors.prisma:
/// Customer account data - This implements the core customer entity requirement from the Customer System requirements document. This model represents end-users who engage in shopping, use personalized features, and manage their own profiles, providing the anchor for all customer-centric activities. Maintains 3NF by separating identity and behavioral data. For example, referenced in orders, addresses, reviews, and behavior logs. Key relationships: links to external accounts, addresses, behavioral tracking. Special behaviors: unique constraints on identity; deletion triggers anonymization except for compliance logs.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// The customer's primary email address - Implements identity requirement. Used for authentication and notifications. Enforces normalization by not duplicating across other tables. For example: unique login/email mapping. Must be unique.
  email String

  /// Customer’s primary phone number. Implements alternative contact requirement. Kept atomic. Used for SMS notification and verification flows. Example: profile edit, password reset.
  phone String

  /// Secure hashed password for the customer. Implements authentication requirement. Ensures security by never storing plain text. Used during login. Null for external-only accounts.
  password_hash String?

  /// Account status (e.g., active, suspended, pending, deleted). Implements status tracking. Maintains normalization as atomic code. Example usage: onboarding approval, account lock.
  status String

  /// Timestamp of account creation. Implements audit trail. Kept atomic and fully normalized. Used for registration analytics.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last profile update. Implements audit and integrity requirement. Tracked for compliance/logging.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  aimall_backend_external_accounts aimall_backend_external_accounts[]
  aimall_backend_behavior_trackings aimall_backend_behavior_trackings[]
  aimall_backend_addresses aimall_backend_addresses[]
  aimall_backend_posts aimall_backend_posts[]
  aimall_backend_comments aimall_backend_comments[]
  aimall_backend_reviews aimall_backend_reviews[]
  aimall_backend_snapshots aimall_backend_snapshots[]
  aimall_backend_carts aimall_backend_carts?
  aimall_backend_orders aimall_backend_orders[]
  aimall_backend_coupons aimall_backend_coupons[]
  aimall_backend_coupon_redemptions aimall_backend_coupon_redemptions[]
  aimall_backend_loyalty_transactions aimall_backend_loyalty_transactions[]
  aimall_backend_abuse_incidents aimall_backend_abuse_incidents[]
  aimall_backend_support_tickets aimall_backend_support_tickets[]

  @@unique([email])
  @@unique([phone])
  @@index([created_at])
}

/// Seller account record - Implements the seller onboarding and management requirement from the Seller System requirements. Each record represents a merchant business identity for listing, inventory management, and analytics. Maintains 3NF by storing only atomic seller-level data. Related to permissions for advanced controls. Example: referenced when tracking seller performance or auditing onboarding. Key relationships: may reference granular permission entity. Special behaviors: Verification/check/audit status handled via status field.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller’s registered business name. Implements business profile requirement. Normalized to avoid duplication in product or order records. Used for display and compliance checks.
  business_name String

  /// Seller’s business contact email. Used for onboarding, notification, and login if allowed. Maintains uniqueness and normalization. For example: used in seller sign-up, password reset.
  email String

  /// Seller’s primary contact phone. Implements communication and verification requirement. Purely atomic and for contact purposes.
  contact_phone String

  /// Onboarding and operational status (pending, approved, rejected, suspended). Used for permission logic and admin review flows. Example: audit transitions, dashboard access.
  status String

  /// Timestamp of seller account creation. For audit and compliance. Example: onboarding analytics.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last seller account update. For audit, change tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  aimall_backend_products aimall_backend_products[]
  aimall_backend_orders aimall_backend_orders[]

  @@unique([email])
  @@index([created_at])
  @@index([business_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Platform administrator entity - Implements the administrator user management and permission assignment requirement. Stores atomic data for each admin-level user with assigned permissions. Maintains 3NF by not mixing with seller/customer logic. Used for full or scoped admin access, activity logging, and audit traceability. Example: System operator signs in and manages sellers. Key relationships: references permissions entity for role assignments.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_administrators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// References {@link aimall_backend_permissions.id} for assigned admin permission set. Enables hierarchical controls. For example: super admin vs. support admin.
  permission_id String @db.Uuid

  /// Administrator’s email address. Used for sign-in and notification. Must be unique. Normalized.
  email String

  /// Administrator display name. Implements admin user naming requirement. Used for dashboard, audit logs. Kept atomic and normalized, not duplicated elsewhere.
  name String

  /// Operational status (active, suspended, pending). Used for access gating and audit flows.
  status String

  /// Creation date for admin account. Used for join analysis, audit trace.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin_permission aimall_backend_permissions @relation(fields: [permission_id], references: [id], onDelete: Cascade)

  aimall_backend_support_tickets aimall_backend_support_tickets[]
  aimall_backend_audit_logs aimall_backend_audit_logs[]

  @@index([permission_id])

  @@unique([email])
  @@index([created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Permission/role definition entity - Implements fine-grained and role-based permission requirements for sellers and administrators. Enables maintainable, extendable, reusable access control lists. Maintains full normalization; only the permission identity and description live here. Example: support admin, super admin, seller-inventory. Used as assignment in admin and seller models. Special behaviors: If altered, triggers audit trail. Relationship: referenced by administrator or seller for role mapping.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_permissions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique code or name for this permission/role (e.g., super_admin, seller_product_manager). Implements unique constraint for RBAC mapping. Maintains normalization; referenced only as foreign key.
  name String

  /// Display name for UI/analytics. Used on dashboards. Not necessarily unique. Maintained separately from permission code for localization/flexibility.
  display_name String

  /// Detailed explanation of what this permission grants. Used for system documentation, admin UX. Maintains atomicity by avoiding embedded business logic.
  description String

  /// Permission definition created timestamp. Used for audit trail and change tracking.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  aimall_backend_administrators aimall_backend_administrators[]

  @@unique([name])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// External identity account link - Implements federated login/OAuth requirements by tracking external provider identities (Google, Kakao, Apple, etc.) linked to primary AIMall customer accounts. Maintains strict normalization: all external linkage data is atomic and sits in this model, referenced from customers. Example: Single customer, multiple federated logins. Relationships: FK to aimall_backend_customers. Special behaviors: If deleted, only impacts authentications via provider.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_external_accounts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer’s {@link aimall_backend_customers.id}. Links this external account to the internal primary customer.
  customer_id String @db.Uuid

  /// Identity provider code (e.g., google, kakao, apple). Enforces normalized provider codes for robust branching and validation. For example: login flow decision logic. Critical for OAuth mapping.
  provider String

  /// External provider’s user ID string. Used to correlate federated identities. Example: store Google sub or Kakao id. Always atomic and never repeated.
  external_user_id String

  /// Timestamp of account linkage. Enables audit trail for identity events. Used for UX (showing when account was linked).
  linked_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  external_account_customer aimall_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@unique([provider, external_user_id])
  @@index([customer_id])
}

/// Per-customer behavioral tracking - Implements the session/activity tracking requirement. Stores API-driven customer events, preferences, and actions for AI, analytics, compliance. Ensures 3NF by isolating behavioral actions from static identity data. Example usage: shopping session event logs, personalization input. Relationship: links to customer. Special behaviors: May be periodically purged/anonymized for compliance. Used only for analytics/AIOps, never for business-critical identities.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_behavior_trackings {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related customer’s {@link aimall_backend_customers.id}. Logs which customer generated the behavior.
  customer_id String @db.Uuid

  /// What user activity/event is being tracked (e.g., login, view_product, add_cart, checkout, search, recommend_click). Implements event-type requirement. Kept atomic as string code; normalization enforced. Used in analytics pipeline for behavior modeling.
  event_type String

  /// Serialized payload describing the event more fully (JSON or similar). Contains atomic data, avoids schema transitive dependency. For example: product IDs, referer, AB test cohort.
  event_data String

  /// Timestamp the event was logged. Implements audit and analytics timing. Used in analytics; always atomic.
  occurred_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  behavior_tracking_customer aimall_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@index([customer_id, occurred_at])
}

/// Customer delivery addresses - Implements the address management requirement, storing normalized and per-customer-linked delivery location data. Ensures all address data is atomic (split lines, etc) in full compliance with 3NF. Used for checkout, shipments, address book UX. Relationships: links customer. Special behaviors: Customers can have multiple addresses, with optional default flag. Deletion disables only for this customer.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_addresses {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner customer’s {@link aimall_backend_customers.id}. Allows associating multiple addresses per account, and enables easy lookup for checkout flows and address book UX.
  customer_id String @db.Uuid

  /// User-defined label for quick selection (e.g., 'Home', 'Office'). Implements per-customer usability. Fully atomic; not duplicated across tables. Used in address picker UX.
  alias String

  /// Address recipient name (can differ from customer profile). Fulfills logistics requirement. Used when generating shipping labels. Always atomic.
  recipient_name String

  /// Phone number for this address/recipient. Meets delivery carrier and communication needs. Fully atomic.
  phone String

  /// Main line of street address/location. Split for normalization; no embedded logic. Used in shipping and verification.
  address_line1 String

  /// Second line (optional, e.g., apartment/suite). Split for normalization; not duplicated. Optional for UX.
  address_line2 String?

  /// City of the address. Used for logistics analysis; atomic for filtering/aggregation.
  city String

  /// Postal/ZIP code. Maintains normalization, index for geo lookup.
  postal_code String

  /// Country code or name. Normalized string for international handling; used for compliance/shipping.
  country String

  /// True if this is the primary/default address for the customer. Implements default selection UX. Only one per customer can be true. Constraint enforced by application logic.
  is_default Boolean

  /// When this address was last modified. Used for audit trail and UX.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  address_customer aimall_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  aimall_backend_orders aimall_backend_orders[]
  aimall_backend_shipments aimall_backend_shipments[]

  @@index([customer_id])
}

schemas.schema-03-products.prisma:
/// Product master (core SKU/group) - This implements the comprehensive product catalog requirement from the Product Management document. Central record for all products listed across the platform. Holds product metadata, primary relationships (category, seller), and references to options and bundles. Maintains 3NF by not duplicating inventory, option, or category data – all relationships via foreign keys. For example, sellers define products here, and inventory or options are in linked tables. Key relationships: links to aimall_backend_sellers (already created table) and aimall_backend_categories. Special behaviors: Only normalized product master data; no precomputed inventory, price, or reviews.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_products {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each product.
  id String @id @db.Uuid

  /// Category's {@link aimall_backend_categories.id}. References which category this product belongs to.
  category_id String @db.Uuid

  /// Seller's {@link aimall_backend_sellers.id} - Who owns this product (from Actors domain; reference only).
  seller_id String @db.Uuid

  /// Product title - Implements product listing requirement. Human-readable product name. Ensures normalization as only master copy here. Example: 'Apple AirPods Pro 2'.
  title String

  /// Product detail/description - Implements product content requirement. Long text explaining features. Normalized; not duplicated elsewhere. Example: 'Latest model, improved noise cancellation.'
  description String?

  /// Main thumbnail image URI - Implements image management requirement. Single main image URI. Only stored here, not duplicated in options. Example: 'https://cdn/airpods2-thumb.jpg'.
  main_thumbnail_uri String? @db.VarChar(80000)

  /// Status of product (active, inactive, out_of_stock, deleted) - Tracks whether product is available. Normalized field. Example: 'active'.
  status String

  /// Created timestamp - Implements audit and snapshot needs. Creation datetime. Example: 2024-05-01T10:00:00Z.
  created_at DateTime @db.Timestamptz

  /// Updated timestamp. To support change and audit needs. Example: 2024-05-02T15:10:00Z.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_aimall_backend_products_category_id aimall_backend_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)
  fk_aimall_backend_products_seller_id aimall_backend_sellers @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  aimall_backend_product_options aimall_backend_product_options[]
  aimall_backend_product_bundles_of_bundle_product_id aimall_backend_product_bundles[] @relation("aimall_backend_product_bundles_of_bundle_product_id")
  aimall_backend_product_bundles_of_component_product_id aimall_backend_product_bundles[] @relation("aimall_backend_product_bundles_of_component_product_id")
  aimall_backend_skus aimall_backend_skus[]
  aimall_backend_inventory_snapshots aimall_backend_inventory_snapshots[]
  aimall_backend_channel_assignments aimall_backend_channel_assignments[]
  aimall_backend_reviews aimall_backend_reviews[]
  aimall_backend_snapshots aimall_backend_snapshots[]
  aimall_backend_cart_items aimall_backend_cart_items[]
  aimall_backend_order_items aimall_backend_order_items[]

  @@unique([seller_id, title])
  @@index([category_id])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product options (variant definitions) - Implements the SKU/variant requirement in the Product Management and ERD. Stores all option variants for products (e.g., color, size). Maintains 3NF by only referencing products and not duplicating inventory or price. For example, 'Color: Black', 'Size: M' for given product. Key relationships: links to aimall_backend_products. Special behaviors: One record per option value; combinations for full SKU are stored in aimall_backend_skus.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_product_options {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique per product option.
  id String @id @db.Uuid

  /// Product's {@link aimall_backend_products.id} - Which product this option belongs to.
  product_id String @db.Uuid

  /// Option name (e.g., Color, Size) - Implements option specification requirement. Atomic; not duplicated. For example, 'Color'.
  name String

  /// Option value (e.g., Red, Large) - Option value per option type. Ensures full normalization. For example, 'Black'.
  value String

  //----
  // RELATIONS
  //----
  fk_aimall_backend_product_options_product_id aimall_backend_products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  aimall_backend_cart_items aimall_backend_cart_items[]
  aimall_backend_order_items aimall_backend_order_items[]

  @@unique([product_id, name, value])
  @@index([product_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([value(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product bundles (set/group of products) - Implements the bundle/package product requirement from Product Management. Defines relationships between products that are sold together as bundles. Strictly normalized: just references to master products and role (main vs component). Never includes precomputed price or stock. For example, 'Gift Set' containing three products. Key relationships: links to main product and bundled product (both aimall_backend_products). Special behaviors: For M:N bundles, each row links a bundle and a bundled component.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_product_bundles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique per bundle-member relation.
  id String @id @db.Uuid

  /// Main bundle product's {@link aimall_backend_products.id}. Represents the product that is a bundle group/master.
  bundle_product_id String @db.Uuid

  /// Bundled component product's {@link aimall_backend_products.id}. Represents the directly included (child) product.
  component_product_id String @db.Uuid

  /// Indicates if the component is required for the bundle - Implements bundle rule requirement. For example, requiring all components for fixed set; false for optional (e.g., gift add-on).
  is_required Boolean

  /// Quantity of this component in the bundle - How many units included per bundle. Maintains normalization by not duplicating product details. Example: 2 means two of this item per bundle.
  quantity Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_aimall_backend_product_bundles_bundle_product_id aimall_backend_products @relation("aimall_backend_product_bundles_of_bundle_product_id", fields: [bundle_product_id], references: [id], onDelete: Cascade)
  fk_aimall_backend_product_bundles_component_product_id aimall_backend_products @relation("aimall_backend_product_bundles_of_component_product_id", fields: [component_product_id], references: [id], onDelete: Cascade)

  @@index([component_product_id])

  @@unique([bundle_product_id, component_product_id], map: "aimall_backend_product_bundles_bundle_product_id_compo_b1a8e08d")
  @@index([bundle_product_id])
}

/// Product categories (taxonomy) - Implements category management and classification from Product Management. Defines the product taxonomy hierarchy (main/sub/section levels). Maintains 3NF – only category data; no product fields here. For example, 'Electronics > Phones > Accessories'. Key relationships: can be hierarchical via parent_id (self-reference); products reference categories. Special behaviors: Hierarchical nesting is optional (nullable parent_id); root categories have null parent_id.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model aimall_backend_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique per category.
  id String @id @db.Uuid

  /// Parent category's {@link aimall_backend_categories.id}. Hierarchical parent, or null for root categories.
  parent_id String? @db.Uuid

  /// Category name - Implements taxonomy labeling. Atomic; no category hierarchy in this field. For example: 'Electronics'.
  name String

  /// Hierarchy depth - Root=1, increasing with subcategories. Implements hierarchy requirement. For example, 2 for subcategory.
  depth Int @db.Integer

  //----
  // RELATIONS
  //----
  fk_aimall_backend_categories_parent_id aimall_backend_categories? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  aimall_backend_products aimall_backend_products[]
  recursive aimall_backend_categories[] @relation("recursive")

  @@unique([parent_id, name])
  @@index([parent_id])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// SKU master (variant combinations) - Implements complete variant/SKU specification from Product Management. Defines each purchasable SKU (combination of product + options), with references to all option values selected. Fully normalized: no pricing, inventory, or calculated data; only references and atomic SKU codes. For example, a unique SKU for 'AirPods Pro 2, Color: Black, Case: Yes'. Key relationships: links to product and all relevant options. Special behaviors: Unique per product and option combination.
